PAYLOAD_SHA256='dbfe8339e48d35acbcb3523a97f36e215154cae583d13b1b8af3e7c3e1aa0e89'

def unpack_payload():
    raw=base64.b85decode(PAYLOAD.encode())
    if hashlib.sha256(raw).hexdigest()!=PAYLOAD_SHA256:raise ValueError('Embedded payload checksum mismatch')
    with zipfile.ZipFile(io.BytesIO(raw)) as archive:
        files={}
        for info in archive.infolist():
            p=PurePosixPath(info.filename)
            if p.is_absolute() or len(p.parts)!=1 or '..' in p.parts or '\\' in info.filename or info.file_size>4_000_000:
                raise ValueError('Invalid embedded path or size')
            if info.filename in files:raise ValueError('Duplicate embedded path')
            files[info.filename]=archive.read(info)
    return files

def check_files(files):
    manifest=json.loads(files['release-manifest.json'])
    if set(manifest)!=set(files)-{'release-manifest.json'}:raise ValueError('Manifest membership mismatch')
    for name,expected in manifest.items():
        if hashlib.sha256(files[name]).hexdigest()!=expected:raise ValueError('Source checksum mismatch: '+name)
        if name.endswith('.py'):ast.parse(files[name].decode('utf-8'),filename=name)
    return hashlib.sha256(files['release-manifest.json']).hexdigest()[:20]

def atomic_json(path,value):
    tmp=path.with_suffix('.tmp');tmp.write_text(json.dumps(value,indent=2),encoding='utf-8');os.replace(tmp,path)

def validate_release(release,python,data):
    commands=[[str(python),'-m','pip','check'],[str(python),'alpha50x_validate.py','--data',str(data)]]
    for i,cmd in enumerate(commands):
        with (data/('installer-validation-'+str(i)+'.log')).open('w',encoding='utf-8') as log:
            result=subprocess.run(cmd,cwd=release,stdout=log,stderr=subprocess.STDOUT,timeout=300)
        if result.returncode:raise RuntimeError('Local validation failed; see installer-validation-'+str(i)+'.log')
    report=json.loads((data/'acceptance.json').read_text())
    if report.get('passed') is not True:raise RuntimeError('Acceptance report missing success')

LAUNCHER='''from pathlib import Path
import json,os,sys,subprocess,time
root=Path(__file__).resolve().parent
info=json.loads((root/'current.json').read_text(encoding='utf-8'))
release=(root/'releases'/info['release']).resolve()
if release.parent != (root/'releases').resolve(): raise SystemExit('Invalid release path')
python=info['python']
if info.get('mcp_python'):os.environ['ALPHA50X_MCP_PYTHON']=info['mcp_python']
else:os.environ.pop('ALPHA50X_MCP_PYTHON',None)
options=list(sys.argv[1:]);background='--background' in options;child='--supervised-background' in options
no_browser='--no-browser' in options
options=[v for v in options if v not in ('--background','--supervised-background','--no-browser')]
port=int(options[options.index('--port')+1]) if '--port' in options else 8765
if not 1024<=port<=65535:raise SystemExit('Invalid local port')
if background:
    try:
        from urllib.request import urlopen
        with urlopen('http://127.0.0.1:'+str(port)+'/api/unified/state',timeout=1) as response:state=json.load(response)
        if state.get('paper_only') is True:
            if not no_browser:
                import webbrowser
                webbrowser.open('http://127.0.0.1:'+str(port)+'/terminal')
            raise SystemExit(0)
    except (OSError,ValueError):pass
    logs=root/'data'/'logs';logs.mkdir(parents=True,exist_ok=True)
    windowless=Path(python).with_name('pythonw.exe') if os.name=='nt' else Path(python)
    if not windowless.is_file():windowless=Path(python)
    with (logs/'background-launcher.log').open('ab') as out:
        subprocess.Popen([str(windowless),str(Path(__file__).resolve()),'--supervised-background',*(['--no-browser'] if no_browser else []),*options],stdin=subprocess.DEVNULL,stdout=out,stderr=subprocess.STDOUT,close_fds=True,creationflags=getattr(subprocess,'CREATE_NO_WINDOW',0),start_new_session=os.name!='nt')
    raise SystemExit(0)
if child:
    lock=open(root/'data'/'background-launcher.lock','a+b');lock.write(b'0');lock.flush();lock.seek(0)
    try:
        if os.name=='nt':
            import msvcrt
            msvcrt.locking(lock.fileno(),msvcrt.LK_NBLCK,1)
        else:
            import fcntl
            fcntl.flock(lock,fcntl.LOCK_EX|fcntl.LOCK_NB)
    except OSError:raise SystemExit(0)
args=[python,str(release/'alpha50x_runtime.py'),'--data',str(root/'data'),'--config',str(root/'config.json'),*(['--open-browser'] if not no_browser else []),*options]
def update_requested():
    try:
        path=root/'data'/'update-request.json'
        if path.stat().st_size>512:return False
        request=json.loads(path.read_text(encoding='utf-8'))
        return request.get('action')=='shutdown_for_update' and 0<=time.time()*1000-int(request['requested_ms'])<=120000
    except (OSError,ValueError,KeyError,TypeError):return False
failures=0
while True:
    if update_requested():raise SystemExit(0)
    started=time.monotonic()
    try:
        result=subprocess.run(args)
    except KeyboardInterrupt:
        raise SystemExit(0)
    if result.returncode==0: raise SystemExit(0)
    if time.monotonic()-started>300:failures=0
    failures+=1
    delay=min(2**min(failures,6),60)
    print('Service exited; restarting the selected PAPER mode in '+str(delay)+' seconds.',flush=True)
    for _ in range(delay):
        if update_requested():raise SystemExit(0)
        time.sleep(1)
'''


def hydrate_existing_seed(files,target):
    # The public updater contains no user database. Recover only the immutable
    # seed belonging to the previously installed release, never the live ledger.
    name='alpha50x_migrated_v4.sqlite'
    if name in files:return files
    target=Path(target).expanduser().resolve()
    current=target/'current.json'
    if not current.is_file():
        raise RuntimeError('This is an UPDATE for an existing Alpha50X installation. No user database is included. Keep the previous installation and contact your assistant.')
    release=json.loads(current.read_text(encoding='utf-8'))['release']
    if not isinstance(release,str) or not release or release in ('.','..') or '/' in release or '\\' in release:
        raise ValueError('Invalid existing release path')
    releases=(target/'releases').resolve();source=(releases/release).resolve()
    seed=(source/name).resolve()
    if source.parent!=releases or seed.parent!=source:
        raise ValueError('Invalid existing seed path')
    expected=json.loads(files['release-manifest.json'])[name]
    data=seed.read_bytes()
    if hashlib.sha256(data).hexdigest()!=expected:
        raise ValueError('Existing immutable seed checksum does not match. The working portfolio has not been changed.')
    return {**files,name:data}

def install(target,*,use_current=False,files=None,validator=validate_release):
    if sys.version_info<(3,11):raise RuntimeError('Python 3.11 or newer required; Python 3.12 is the validated Linux runtime')
    files=unpack_payload() if files is None else files;files=hydrate_existing_seed(files,target);release_id=check_files(files)
    target=Path(target).expanduser().resolve()
    if target.exists() and any(target.iterdir()) and not (target/'current.json').is_file() and not (target/'.alpha50x-install').is_file():
        raise RuntimeError('Choose an empty directory or an existing unified Alpha50X installation; original files are not overwritten')
    target.mkdir(parents=True,exist_ok=True)
    marker=target/'.alpha50x-install'
    if not marker.exists():marker.write_text('Alpha50X unified installer v1\n',encoding='utf-8')
    # Use the OS lock before touching an existing deployment or its live data.
    lock_file=open(target/'.install.lock','a+b');lock_file.write(b'0');lock_file.flush();lock_file.seek(0)
    try:
        if os.name=='nt':
            import msvcrt
            msvcrt.locking(lock_file.fileno(),msvcrt.LK_NBLCK,1)
        else:
            import fcntl
            fcntl.flock(lock_file,fcntl.LOCK_EX|fcntl.LOCK_NB)
    except OSError:lock_file.close();raise RuntimeError('Another installer is running') from None
    release=target/'releases'/release_id;created=False;owned_service_lock=None
    # Acceptance reports are stored per release; never overwrite a running
    # installation's validation evidence until the new release has passed.
    validation_data=target/'validation'/release_id
    old_pointer=(target/'current.json').read_bytes() if (target/'current.json').exists() else None
    managed=('start_alpha50x.py','start_alpha50x.cmd','config.json','data/acceptance.json','install-report.json')
    prior={name:(target/name).read_bytes() if (target/name).is_file() else None for name in managed}
    try:
        if (target/'data'/'paper.sqlite').exists():
            # Load only our validated embedded lock helper, not installed arbitrary code.
            namespace={'__name__':'installer_helpers'}
            exec('import os\n'+ast.get_source_segment(files['alpha50x_core.py'].decode(),next(n for n in ast.parse(files['alpha50x_core.py']).body if isinstance(n,ast.ClassDef) and n.name=='InstanceLock')),namespace)
            owned_service_lock=namespace['InstanceLock'](target/'data'/'service.lock')
            backup=target/'backups'/('paper-'+str(time.time_ns())+'.sqlite');backup.parent.mkdir(exist_ok=True)
            with closing(sqlite3.connect((target/'data'/'paper.sqlite').as_uri()+'?mode=ro',uri=True)) as src,closing(sqlite3.connect(backup)) as dst:
                src.backup(dst)
                if dst.execute('PRAGMA integrity_check').fetchone()!=('ok',):raise RuntimeError('Backup integrity check failed')
        if not release.exists():
            release.mkdir(parents=True);created=True
            for name,content in files.items():(release/name).write_bytes(content)
        else:
            for name,content in files.items():
                if not (release/name).is_file() or (release/name).read_bytes()!=content:raise RuntimeError('Existing release was modified; refusing overwrite')
        with closing(sqlite3.connect((release/'alpha50x_migrated_v4.sqlite').as_uri()+'?mode=ro',uri=True)) as db:
            if db.execute('PRAGMA integrity_check').fetchone()!=('ok',):raise RuntimeError('Seed database integrity failed')
        if use_current:
            python=Path(sys.executable)
            subprocess.run([str(python),'-c','import aiohttp, websockets; from zoneinfo import ZoneInfo; ZoneInfo("America/New_York")'],check=True,capture_output=True)
        else:
            envdir=release/'.venv';python=envdir/('Scripts/python.exe' if os.name=='nt' else 'bin/python')
            if not python.is_file():venv.EnvBuilder(with_pip=True).create(envdir)
            validation_data.mkdir(parents=True,exist_ok=True)
            with (validation_data/'dependency-install.log').open('w',encoding='utf-8') as log:
                subprocess.run([str(python),'-m','pip','install','--disable-pip-version-check','-r',str(release/'requirements.txt')],stdout=log,stderr=subprocess.STDOUT,check=True,timeout=300)
        mcp_python=None
        mcp_requirements=release/'requirements-mcp.txt'
        if mcp_requirements.is_file():
            constraints=release/'constraints-mcp.txt'
            runtime_id=hashlib.sha256(mcp_requirements.read_bytes()+(constraints.read_bytes() if constraints.exists() else b'')+sys.version.encode()+os.name.encode()).hexdigest()[:20]
            mcp_env=target/'mcp-runtime'/runtime_id
            mcp_python=mcp_env/('Scripts/python.exe' if os.name=='nt' else 'bin/python')
            if not mcp_python.is_file():venv.EnvBuilder(with_pip=True).create(mcp_env)
            validation_data.mkdir(parents=True,exist_ok=True)
            with (validation_data/'mcp-install.log').open('w',encoding='utf-8') as log:
                subprocess.run([str(mcp_python),'-m','pip','install','--disable-pip-version-check','-r',str(mcp_requirements)],stdout=log,stderr=subprocess.STDOUT,check=True,timeout=300)
                subprocess.run([str(mcp_python),'-m','pip','check'],stdout=log,stderr=subprocess.STDOUT,check=True,timeout=60)
                subprocess.run([str(mcp_python),'-c','import fastmcp,alpaca_mcp_server,jsonschema'],stdout=log,stderr=subprocess.STDOUT,check=True,timeout=60)
                if (release/'alpha50x_mcp_smoke.py').is_file():subprocess.run([str(mcp_python),str(release/'alpha50x_mcp_smoke.py')],stdout=log,stderr=subprocess.STDOUT,check=True,timeout=90,cwd=release)
        validation_data.mkdir(parents=True,exist_ok=True);validator(release,python,validation_data)
        # Initialize only a missing working database. No tests run against user data.
        data=target/'data';data.mkdir(exist_ok=True)
        if not (data/'paper.sqlite').exists():
            with closing(sqlite3.connect((release/'alpha50x_migrated_v4.sqlite').as_uri()+'?mode=ro',uri=True)) as src,closing(sqlite3.connect(data/'paper.sqlite')) as dst:src.backup(dst)
        launcher=target/'start_alpha50x.py'
        if launcher.exists() and launcher.read_text(encoding='utf-8')!=LAUNCHER and hashlib.sha256(launcher.read_text(encoding='utf-8').encode()).hexdigest() not in ('e92ec26b0ec2ef87748605d77c4b4f11609137c26ef40c25ef6dc2368bdd6ba8','72f98c8c549b60834ca4955161fdfe4cc259a6eb2809176da60ad793f5b77a66','3577bfa550b56f1964abec4e5b8c50782e4ab5b0aad00a416f34d47fbc3a5b01'):raise RuntimeError('User-modified launcher preserved; refusing overwrite')
        launcher.write_text(LAUNCHER,encoding='utf-8')
        # Keep the .cmd ASCII: expanded %~dp0 preserves Unicode installation
        # paths without depending on the console's active OEM code page.
        cmd='@echo off\r\nwhere py >nul 2>nul\r\nif errorlevel 1 (\r\n  python "%~dp0start_alpha50x.py" %*\r\n) else (\r\n  py -3 "%~dp0start_alpha50x.py" %*\r\n)\r\n'
        (target/'start_alpha50x.cmd').write_text(cmd,encoding='utf-8')
        config=target/'config.json'
        if not config.exists():config.write_bytes(files['config.example.json'])
        shutil.copy2(validation_data/'acceptance.json',data/'acceptance.json')
        atomic_json(target/'current.json',{'release':release_id,'python':str(python),'mcp_python':str(mcp_python) if mcp_python else None})
        report={'installed':True,'release':release_id,'target':str(target),'source_checksums_verified':True,'tests':'PASS',
                'paper_execution':'PAUSED','existing_ledger':'preserved','live_providers':'NOT VERIFIED','windows_ui':'NOT VERIFIED',
                'start_command':str(target/'start_alpha50x.cmd') if os.name=='nt' else str(python)+' '+str(launcher)}
        atomic_json(target/'install-report.json',report);return report
    except BaseException:
        for name,content in prior.items():
            path=target/name
            if content is None:path.unlink(missing_ok=True)
            else:path.write_bytes(content)
        if old_pointer is not None:(target/'current.json').write_bytes(old_pointer)
        else:(target/'current.json').unlink(missing_ok=True)
        if created:shutil.rmtree(release)
        raise
    finally:
        if owned_service_lock:owned_service_lock.close()
        lock_file.close()

def main(argv=None):
    p=argparse.ArgumentParser(description='Self-contained Alpha50X PAPER Windows installer')
    p.add_argument('--target',type=Path,default=Path.cwd()/'Alpha50X')
    p.add_argument('--use-current-python',action='store_true',help='Use already prepared interpreter instead of creating a venv')
    args=p.parse_args(argv)
    try:print(json.dumps(install(args.target,use_current=args.use_current_python),indent=2));return 0
    except Exception as exc:
        # Exceptions from pip/providers may contain credentials; print category only.
        print('Installation failed safely: '+type(exc).__name__+'. Inspect local validation logs; existing portfolio is preserved.',file=sys.stderr);return 1

if __name__=='__main__':raise SystemExit(main())
